const rows = $input.all().map((i) => i.json);

function isRowDone(row) {
  const shopifyUrl = String(row['Shopify Product URL'] || '').trim();
  if (shopifyUrl) return true;
  const status = String(row['Status'] || '').trim().toUpperCase();
  if (['LIVE_DRAFT', 'PUBLISHED'].includes(status)) return true;
  const qa = String(row['QA Status'] || '').trim().toUpperCase();
  const score = Number(row['AI Score'] || 0);
  return (qa === 'PASS' || qa === 'PASS_NO_IMAGE') && score >= 90 && shopifyUrl;
}

function getPrice(row) {
  const p = row['Price'] ?? row['Variant Price'] ?? null;
  if (p === null || p === undefined || String(p).trim() === '') return null;
  return p;
}


function isDirectImageUrl(url) {
  const u = String(url || '').trim().replace(/&amp;/g, '&');
  if (!u.startsWith('http')) return false;
  if (/\.html(?:\?|$|#)/i.test(u)) return false;
  if (/\.(jpe?g|png|webp|gif|avif)(\?|$|#)/i.test(u)) return true;
  if (/\/catalog\/product\//i.test(u)) return true;
  if (/\/wp-content\/uploads\//i.test(u)) return true;
  if (/\/media\/catalog\/product\//i.test(u)) return true;
  if (/\/cdn\/shop\//i.test(u)) return true;
  if (/\/is\/image\//i.test(u)) return true;
  if (/images\.(lululemon|scene7)\./i.test(u)) return true;
  if (/scene7\.com/i.test(u)) return true;
  if (/media\.mango\.com/i.test(u)) return true;
  if (/media\.mango\.com/i.test(u)) return true;
  if (/media\.mango\.com/i.test(u)) return true;
  if (/media\.mango\.com/i.test(u)) return true;
  if (/media\.mango\.com/i.test(u)) return true;
  if (/media\.mango\.com/i.test(u)) return true;
  if (/[?&](?:wid|width|hei|height|fmt|format)=/i.test(u) && /\/(?:is\/image|images?)\//i.test(u)) return true;
  return false;
}

function getProductUrl(row) {
  return String(row['Product URL'] || row['Source URL'] || '').trim();
}

function categoryCode(category) {
  const raw = String(category || '').trim();
  if (!raw) return 'GEN';
  const words = raw.split(/[\s>|/,\-–]+/).map((w) => w.replace(/[^a-zA-Z]/g, '')).filter((w) => w.length > 0);
  if (words.length === 0) return 'GEN';
  if (words.length >= 2) {
    const code = (words[0].slice(0, 2) + words[words.length - 1].slice(0, 2)).toUpperCase();
    return code || 'GEN';
  }
  return words[0].slice(0, 4).toUpperCase() || 'GEN';
}

function randomSkuSuffix(length = 6) {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let out = '';
  for (let i = 0; i < length; i++) out += chars[Math.floor(Math.random() * chars.length)];
  return out;
}

function generateSku(category) {
  const prefix = categoryCode(category).slice(0, 4);
  return `${prefix}-${randomSkuSuffix(6)}`;
}

function needsScrape(row, productUrl) {
  if (!productUrl) return false;
  const status = String(row['Scrape Status'] || '').trim().toUpperCase();
  const lastUrl = String(row['Source Product URL'] || '').trim();
  if (status !== 'SCRAPED') return true;
  if (lastUrl && lastUrl !== productUrl) return true;
  const imageUrl = String(row['Product image URL'] || row.validated_image_url || '').trim();
  const title = String(row['Title'] || '').trim();
  if (!isDirectImageUrl(imageUrl) || !title) return true;
  return false;
}

function normalizeRow(item) {
  const productUrl = getProductUrl(item);
  let category = String(item['Product category'] || item['Type'] || '').trim();
  if (category.startsWith('#') || /error/i.test(category)) category = '';
  let sku = String(item['SKU'] || item['Variant SKU'] || '').trim();
  if (!sku) sku = generateSku(category);
  const imageUrl = String(item['Product image URL'] || item['Image Src'] || item['Image URL'] || '').trim();
  const rawInfo = String(item['Description'] || item['Title'] || '').trim();
  const vendor = item['Vendor'] || item['Brand'] || '';
  const price = getPrice(item);
  const rowNumber = item.row_number ?? item.__rowNumber ?? item.__row ?? null;
  return {
    sku, productUrl, imageUrl, rawInfo, category, vendor, price, rowNumber, item,
    needsScrape: needsScrape(item, productUrl),
  };
}

let chosen = null;
const skipped = [];

for (const raw of rows) {
  if (isRowDone(raw)) {
    skipped.push({ sku: raw['SKU'] || '', reason: 'already PASS' });
    continue;
  }
  const r = normalizeRow(raw);
  const hasUrl = !!r.productUrl;
  const hasManual = r.imageUrl && r.rawInfo && r.price !== null && r.sku;

  if (!hasUrl && !hasManual) {
    skipped.push({ sku: r.sku || '(no sku)', reason: 'no Product URL and incomplete manual row' });
    continue;
  }

  if (hasUrl && r.needsScrape) {
    chosen = { ...r, mode: 'scrape' };
    break;
  }

  if (!r.imageUrl || !r.rawInfo) {
    skipped.push({ sku: r.sku, reason: 'missing image or description after scrape' });
    continue;
  }
  if (r.price === null && !hasUrl) {
    skipped.push({ sku: r.sku, reason: 'no Price' });
    continue;
  }

  chosen = { ...r, mode: hasUrl ? 'url_pipeline' : 'manual' };
  break;
}

if (!chosen) {
  return [{
    json: {
      _workflow_status: 'nothing_to_process',
      _message: 'No row to run. Add a Product URL or complete manual row (image + description + price + SKU).',
      _skipped_rows: skipped,
      _rows_checked: rows.length,
    },
  }];
}

const runId = `${Date.now()}-${chosen.sku}`;

return [{
  json: {
    ...chosen.item,
    row_number: chosen.rowNumber,
    processing_sku: chosen.sku,
    validated_sku: chosen.sku,
    source_product_url: chosen.productUrl,
    scrape_mode: chosen.mode,
    validated_image_url: chosen.imageUrl,
    validated_raw_info: chosen.rawInfo,
    validated_category: chosen.category,
    validated_vendor: chosen.vendor,
    validated_inventory: chosen.item['Inventory quantity'] || chosen.item['Variant Inventory Qty'] || chosen.item['Inventory Qty'] || null,
    validated_price: getPrice(chosen.item),
    needs_scrape: chosen.mode === 'scrape',
    _run_id: runId,
    _skipped_rows: skipped,
  },
}];

const inputItem = $input.first();
let payload = inputItem.json;

if (payload === undefined || payload === null) {
  payload = {};
} else if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch {
    payload = { text: payload };
  }
} else if (Array.isArray(payload)) {
  payload = { items: payload };
} else if (typeof payload !== 'object') {
  payload = { value: payload };
}

const photoroomBinary = $('Remove background Photoroom').first().binary;
if (!photoroomBinary?.data) {
  throw new Error('No image binary from Photoroom (Remove background Photoroom) — cannot upload to ImgBB');
}

// Pass n8n binary reference through — ImgBB multipart handles filesystem-v2 natively.
// Do NOT convert to base64 here (getBinaryDataBuffer fails on cross-node reads).
return [{
  json: payload,
  binary: photoroomBinary,
}];

