  tshirt: 'gid://shopify/TaxonomyCategory/aa-1-13-7',
  't-shirt': 'gid://shopify/TaxonomyCategory/aa-1-13-7',
  dress: 'gid://shopify/TaxonomyCategory/aa-1-13-1',
