  jeans: 'gid://shopify/TaxonomyCategory/aa-1-13-4',
  trouser: 'gid://shopify/TaxonomyCategory/aa-1-13-11',
  pant: 'gid://shopify/TaxonomyCategory/aa-1-13-11',
