const SHEET_FORMULA_KEYS = [
  'Vendor',
  'Product category',
  'Variant profile',
  'Collection',
  'Prompt ID',
  'Prompt Title',
  'Prompt Description',
  'Prompt Tags',
  'Prompt SEO title',
  'Prompt SEO description',
  'Prompt Image alt',
  'Prompt Category',
];

function overlaySheetFormulas(target, source) {
  if (!source || typeof source !== 'object') return target;
  for (const key of SHEET_FORMULA_KEYS) {
    const v = String(source[key] ?? '').trim();
    if (v) target[key] = v;
  }
  return target;
}

